    ("<!doctype html><html lang=en><meta charset=utf-8><title>T</title>\n<div><figcaption>C</figcaption></div>\n", [("error", "Element \u{201c}figcaption\u{201d} not allowed as child of \u{201c}div\u{201d} in this context.")]),
