] as [(String, [(String, String)])])
func tableModelMatchesUpstream(document: String, expected: [(String, String)]) {
    let actual = checkHTML(document).messages
        .filter { "info" != $0.type || "warning" == $0.subType }
        .map { "\("info" == $0.type ? "warning" : "error"): \($0.message)" }
        .sorted()
    #expect(actual == expected.map { "\($0.0): \($0.1)" }.sorted(), "\(document)")
}

// Case 554591 (U11): the same in an XHTML document, whose rows directly in a
// table are in an implicit row group ("Table cell spans past the end of its
// implicit row group", which read "… of its row group established by an
// implicit row group"). The expected messages are vnu.jar's.
@Test(arguments: [
    ("<table><tr><td rowspan=\"3\">a</td></tr><tr><td>b</td></tr></table>", [("error", "Table cell spans past the end of its implicit row group; clipped to the end of the row group."), ("warning", "A table row was 2 columns wide and exceeded the column count established by the first row (1).")]),
    ("<table><tr></tr></table>", [("error", "Row 1 of an implicit row group has no cells beginning on it.")]),
    ("<table><col span=\"2\"/><tr><td>a</td></tr></table>", [("error", "A table row was 1 columns wide, which is less than the column count established using column markup (2)."), ("error", "Element \u{201c}col\u{201d} not allowed as child of \u{201c}table\u{201d} in this context."), ("error", "Table column 2 established by element \u{201c}col\u{201d} has no cells beginning in it.")]),
    ("<table><colgroup span=\"2\"/><tr><th colspan=\"3\">a</th></tr></table>", [("error", "A table row was 3 columns wide and exceeded the column count established using column markup (2)."), ("error", "Table column 2 established by element \u{201c}colgroup\u{201d} has no cells beginning in it."), ("error", "Table column 3 established by element \u{201c}th\u{201d} has no cells beginning in it.")]),
    ("<table><thead><tr><th colspan=\"2\">h</th></tr></thead><tbody><tr><td rowspan=\"2\">a</td><td>b</td></tr><tr><td>c</td></tr></tbody></table>", []),
    ("<table><colgroup><col span=\"2\"/><col/></colgroup><tr><td>a</td><td>b</td></tr><tr></tr></table>", [("error", "A table row was 0 columns wide, which is less than the column count established using column markup (3)."), ("error", "A table row was 2 columns wide, which is less than the column count established using column markup (3)."), ("error", "Row 2 of an implicit row group has no cells beginning on it."), ("error", "Table column 3 established by element \u{201c}col\u{201d} has no cells beginning in it.")]),
    ("<table><tr><td rowspan=\"0\">a</td><td>b</td></tr><tr><td>c</td></tr><tr><td colspan=\"2\">d</td><td>e</td></tr></table>", [("error", "Table column 3 established by element \u{201c}td\u{201d} has no cells beginning in it."), ("warning", "A table row was 4 columns wide and exceeded the column count established by the first row (2).")]),
    ("<table><tr><td>a</td><td rowspan=\"2\">b</td></tr><tr><td colspan=\"2\">c</td></tr></table>", [("error", "Table cell is overlapped by later table cell."), ("error", "Table cell overlaps an earlier table cell.")]),

    ("<table><tr><td colspan=\" 2\">a</td></tr></table>", [("error", "Bad value \u{201c} 2\u{201d} for attribute \u{201c}colspan\u{201d} on element \u{201c}td\u{201d}."), ("error", "Table column 2 established by element \u{201c}td\u{201d} has no cells beginning in it.")]),
    ("<table><template><col span=\"2\"/></template><colgroup span=\"2\"/><tbody><tr><td>a</td><td>b</td><td>c</td><td>d</td></tr></tbody></table>", []),
    ("<table><template><col span=\"3\"/></template><tbody><tr><td>a</td></tr></tbody></table>", [("error", "A table row was 1 columns wide, which is less than the column count established using column markup (3)."), ("error", "Table columns in range 2\u{2026}3 established by element \u{201c}col\u{201d} have no cells beginning in them.")]),
] as [(String, [(String, String)])])
func xhtmlTableModelMatchesUpstream(_ body: String, _ expected: [(String, String)]) {
    let result = NuValidator().check(
        input: DocumentInput(data: Data("<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<html xmlns=\"http://www.w3.org/1999/xhtml\" lang=\"en\"><head><title>T</title></head><body>\n\(body)\n</body></html>\n".utf8), contentType: "application/xhtml+xml; charset=utf-8"),
        options: CheckerOptions(parameters: ["out": ["json"]])
    )
    let actual = result.messages
        .filter { "info" != $0.type || "warning" == $0.subType }
        .map { "\("info" == $0.type ? "warning" : "error"): \($0.message)" }
        .sorted()
    #expect(actual == expected.map { "\($0.0): \($0.1)" }.sorted(), "\(body)")
}

