] as [(String, [(String, Int, Int)])])
func tableMessagesComeInUpstreamsOrderAndPlace(document: String, expected: [(String, Int, Int)]) {
    let actual = checkHTML(document).messages
        .filter { isTableModelMessage($0.message) }
        .map { "\($0.message) @ \($0.firstLine ?? $0.lastLine ?? 0):\($0.firstColumn ?? $0.lastColumn ?? 0)" }
    #expect(actual == expected.map { "\($0.0) @ \($0.1):\($0.2)" }, "\(document)")
}

/// Case 554591 (U11): whether a message is one of the table checker's (see
/// tableMessagesComeInUpstreamsOrderAndPlace).
private func isTableModelMessage(_ message: String) -> Bool {
    let prefixes = ["A table row was", "Row ", "Table column", "Table cell", "The value of the \u{201c}colspan\u{201d}", "The value of the \u{201c}rowspan\u{201d}", "The value of the \u{201c}span\u{201d}", "A col element causes", "The \u{201c}headers\u{201d} attribute"]
    if prefixes.contains(where: { message.hasPrefix($0) }) {
        return true
    }
    return message.hasPrefix("Bad value") && (message.contains("attribute \u{201c}colspan\u{201d}") || message.contains("attribute \u{201c}rowspan\u{201d}"))
}

// Case 554591 (item 3, and the notes' item 7): headings as upstream's parser
// and checkers have them. A heading's start tag closes a heading that is the
// current node ("Heading cannot be a child of another heading."), so the two
// are siblings, where the port nested every heading after an unclosed one in
// it; an h1–h6 end tag closes the innermost heading in scope, whichever of
// the six it is; a heading is "Empty heading." when nothing upstream's
// checker counts has been counted for it (text, or an <img> with a non-empty
// alt, outside templates, each credited to the heading most recently
// opened); and the heading levels are checked in the order the headings
// start, empty ones too, with headingoffset and headingreset. The expected
// messages are vnu.jar's.
