    ("<!doctype html><html lang=en><meta charset=utf-8><title>T</title>\n<h1><math><annotation-xml></h1>x\n", [("End tag \u{201c}h1\u{201d} did not match the name of the current open element (\u{201c}annotation-xml\u{201d}).", 2, 27), ("Stray end tag \u{201c}h1\u{201d}.", 2, 27)]),
