    ("<!doctype html><html lang=en><meta charset=utf-8><title>T</title>\n<h1><math><mi></h1>x\n", [("End tag \u{201c}h1\u{201d} did not match the name of the current open element (\u{201c}mi\u{201d}).", 2, 15), ("Stray end tag \u{201c}h1\u{201d}.", 2, 15)]),
] as [(String, [(String, Int, Int)])])
func headingMessagesComeInUpstreamsPlaces(document: String, expected: [(String, Int, Int)]) {
    let actual = checkHTML(document).messages
        .filter { isHeadingMessage($0.message) }
        .map { "\($0.message) @ \($0.firstLine ?? $0.lastLine ?? 0):\($0.firstColumn ?? $0.lastColumn ?? 0)" }
        .sorted()
    #expect(actual == expected.map { "\($0.0) @ \($0.1):\($0.2)" }.sorted(), "\(document)")
}

/// Case 554591 (item 3): whether a message is about headings (see
/// headingMessagesComeInUpstreamsPlaces).
private func isHeadingMessage(_ message: String) -> Bool {
    let prefixes = ["Heading cannot be a child of another heading.", "Empty heading.", "The heading \u{201c}", "This document has heading elements but none of them"]
    if prefixes.contains(where: { message.hasPrefix($0) }) {
        return true
    }
    return nil != message.range(of: "^(End tag|Stray end tag) \u{201c}h[1-6]\u{201d}", options: .regularExpression)
}

// Case 554591 (A20): date and time values as upstream's datatypes judge them
// (see HTMLDatetimeDatatype): a <time>'s datetime by TimeDatetime, which
// takes years, months, weeks, yearless dates, time-zone offsets and
// durations as well as dates and times, inside optional whitespace; an
// ins's or del's by DatetimeTz or Date; and the date and time input types'
// min, max and value by their own. What upstream only warns about (a year
// before 1000 or from 3000 on, an offset outside UTC−12 to UTC+14 or with
// odd minutes) is a warning. And a <time> without a datetime attribute has
// its text checked against TimeDatetime. The expected messages are vnu.jar's,
// with its datatype warnings worded as TestRunner's ("Bad value …", as a
// warning), as the port words them.
