] as [(String, [(String, String)])])
func datetimeValuesMatchUpstream(document: String, expected: [(String, String)]) {
    let actual = checkHTML(document).messages
        .filter { "info" != $0.type || "warning" == $0.subType }
        .map { "\("info" == $0.type ? "warning" : "error"): \($0.message)" }
        .sorted()
    #expect(actual == expected.map { "\($0.0): \($0.1)" }.sorted(), "\(document)")
}

// Case 554591 (A20): the date and time messages at vnu.jar's line and column
// (its first ones where it gives them, as BBEdit reads them): an attribute's
// at its element's start tag, and a <time>'s text's at its end tag, or at the
// token that closed it implicitly (as the end of the file does, a line lower
// than vnu.jar puts it, the notes' item 45, so those cases aren't here).
// Sorted, as the port's parser and checkers report in separate passes. The
// expected messages are vnu.jar's.
