func ariaRulesMatchUpstream(document: String, expected: [(String, String)]) {
    let actual = checkHTML(document).messages
        .filter { "info" != $0.type || "warning" == $0.subType }
        .map { "\("info" == $0.type ? "warning" : "error"): \($0.message)" }
        .sorted()
    #expect(actual == expected.map { "\($0.0): \($0.1)" }.sorted(), "\(document)")
}

// Case 554591 (A14's third review): where the parser ends the head and starts
// the body, as upstream's tree builder does, and what the checkers that go by
// it then report: text that's whitespace once its references are decoded
// doesn't end the head; a stray table part after </head>, and a </br> before
// the body, start it; a </body> or </html> in a template is ignored; and a
// base after such a start is in the body. Every error and warning, sorted, as
// ariaRulesMatchUpstream compares them; the expected messages are vnu.jar's.
@Test(arguments: [
    ("<!DOCTYPE html>\n<html lang=\"en\"><head><title>t</title></br><base href=\"x/\"></head><body><p>x</p></body></html>\n", [("error", "Element \u{201c}base\u{201d} not allowed as child of \u{201c}body\u{201d} in this context."), ("error", "End tag \u{201c}br\u{201d}."), ("error", "Start tag \u{201c}body\u{201d} seen but an element of the same type was already open."), ("error", "Stray end tag \u{201c}head\u{201d}.")]),
    ("<!DOCTYPE html>\n<html lang=\"en\"><head><title>t</title></head><td><base href=\"x/\"><p>x</p></html>\n", [("error", "Element \u{201c}base\u{201d} not allowed as child of \u{201c}body\u{201d} in this context."), ("error", "Stray start tag \u{201c}td\u{201d}.")]),
    ("<!DOCTYPE html>\n<html lang=\"en\"><head><title>t</title></head><td><body><p>x</p></body></html>\n", [("error", "Start tag \u{201c}body\u{201d} seen but an element of the same type was already open."), ("error", "Stray start tag \u{201c}td\u{201d}.")]),
    ("<!DOCTYPE html>\n<html lang=\"en\"><head><title>t</title></br></head><body><p>x</p></body></html>\n", [("error", "End tag \u{201c}br\u{201d}."), ("error", "Start tag \u{201c}body\u{201d} seen but an element of the same type was already open."), ("error", "Stray end tag \u{201c}head\u{201d}.")]),
    ("<!DOCTYPE html>\n<html lang=\"en\"><head><title>t</title>\nx<base href=\"x/\"></head><body><p>x</p></body></html>\n", [("error", "Element \u{201c}base\u{201d} not allowed as child of \u{201c}body\u{201d} in this context."), ("error", "Start tag \u{201c}body\u{201d} seen but an element of the same type was already open."), ("error", "Stray end tag \u{201c}head\u{201d}.")]),
    ("<!DOCTYPE html>\n<html lang=\"en\"><head><title>t</title>&#10;</head><body><p>x</p></body></html>\n", []),
    ("<!DOCTYPE html>\n<html lang=\"en\"><head><title>t</title>&#32;<base href=\"x/\"></head><body><p>x</p></body></html>\n", []),
    ("<!DOCTYPE html>\n<html lang=\"en\"><head><title>t</title>&#9;\n<base href=\"x/\"></head><body><p>x</p></body></html>\n", []),
    ("<!DOCTYPE html>\n<html lang=\"en\"><head><title>t</title><template></body><meta name=\"x\" content=\"y\" aria-checked=\"true\"></template></head>\n<body><p>x</p></body></html>\n", [("error", "Stray end tag \u{201c}body\u{201d}.")]),
    ("<!DOCTYPE html>\n<html lang=\"en\"><head><title>t</title><template></html><div aria-checked=\"true\">x</div></template></head>\n<body><p>x</p></body></html>\n", [("error", "Stray end tag \u{201c}html\u{201d}.")]),
    ("<!DOCTYPE html>\n<html lang=\"en\"><head><title>t</title></head><td><p>x</p></html>\n", [("error", "Stray start tag \u{201c}td\u{201d}.")]),
] as [(String, [(String, String)])])
func headAndBodyStartsMatchUpstream(document: String, expected: [(String, String)]) {
    let actual = checkHTML(document).messages
        .filter { "info" != $0.type || "warning" == $0.subType }
        .map { "\("info" == $0.type ? "warning" : "error"): \($0.message)" }
        .sorted()
    #expect(actual == expected.map { "\($0.0): \($0.1)" }.sorted(), "\(document)")
}

