    ("<!doctype html><html lang=en><meta charset=utf-8><title>T</title>\n<svg width=\"0\" height=\"0\"><symbol id=\"i\" viewBox=\"0 0 1 1\"><path d=\"M0 0h1\"/></symbol></svg><svg width=\"16\" height=\"16\"><use href=\"#i\"/></svg>\n", []),
