func foreignContentMatchesUpstream(document: String, expected: [(String, String)]) {
    let actual = checkHTML(document).messages
        .filter { $0.type != "info" || $0.subType == "warning" }
        .map { "\($0.type == "info" ? "warning" : "error"): \($0.message)" }
        .sorted()
